import { CURRICULUM_DATA } from './curriculum';

export interface ChapterConcept {
  title: string;
  description: string;
  formulas?: string[]; // 每條公式獨立一列
  diagramType?: string; // 幾何圖像視覺化
  diagramPosition?: 'bottom' | 'right' | 'top'; // 圖像放置位置（預設下方，公式短時可放右側，亦可放最上方）
  track?: 'common' | 'mathA' | 'mathB'; // 標註為共同、數A專屬或數B專屬
}

export interface SopModule {
  moduleName: string;
  question?: string;
  mindset?: string;
  diagramType?: string;
  steps: { label: string; text: string }[];
  answer?: string;
}

export interface ClassicExample {
  title: string;
  question: string;
  diagramType?: string;
  solutionSteps: { step: string; content: string }[];
  answer?: string;
}

export interface QuizQuestion {
  questionNumber: number;
  title: string;
  question: string;
  diagramType?: string;
  hint?: string;
}

export interface TrackVariant {
  scopeNotice?: string;
  ahaInsight?: string;
  coreConcepts?: ChapterConcept[];
  pitfalls?: string[];
  sopModules?: SopModule[];
  classicExamples?: ClassicExample[];
  quizQuestions?: QuizQuestion[];
}

export interface ChapterSummary {
  chapter: string;
  mathTrack?: 'mathA' | 'mathB' | 'common' | 'none'; // 數A / 數B / 數A+B共同 / 非高中數學
  scopeNotice?: string; // 課綱進度與考試定位
  ahaInsight: string; // 核心觀念精要
  coreConcepts: ChapterConcept[];
  pitfalls: string[]; // 常見迷思與避坑提醒
  sopModules?: SopModule[]; // 老師獨家破題思維（解題 SOP）
  classicExamples?: ClassicExample[]; // 經典範例與步驟化詳解
  quizQuestions?: QuizQuestion[]; // 課後微檢測（觀念思考題）
  trackVariants?: {
    common?: TrackVariant;
    mathA?: TrackVariant;
    mathB?: TrackVariant;
  };
}

